entry.string:
// This script executes once for each deploy, undeploy, or redeploy task
// if at least one channel was undeployed
// You only have access to the globalMap here to persist data
return;

// This script executes once after a message has been processed
// This script applies across all channels
// Responses returned from here will be stored as "Postprocessor" in the response map
// You have access to "response", if returned from the channel postprocessor
return;

// Initialize shared UUID generator once, before channels start processing messages
if (globalMap.get('UUID_GENERATOR') == null) {
    globalMap.put('UUID_GENERATOR', Packages.com.fasterxml.uuid.Generators.timeBasedEpochGenerator());
}

// Modify the message variable below to pre process data
// This script applies across all channels
return message;
